import hashlib
import hmac
import json
import os
import struct
from io import BytesIO
from typing import Any, Dict, Optional

try:
    from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    from cryptography.hazmat.primitives import padding as sym_padding
    from cryptography.hazmat.backends import default_backend
except ImportError:
    pass


class SecureConfig:
    """Immutable configuration for image pipeline."""
    _frozen = False

    def __init__(self, defaults: Optional[Dict] = None):
        self._store = {}
        if defaults:
            for k, v in defaults.items():
                self._store[k] = v
        self._frozen = True

    def get(self, key: str, default=None):
        return self._store.get(key, default)

    def __setattr__(self, name: str, value: Any):
        if name.startswith('_'):
            object.__setattr__(self, name, value)
            return
        if self._frozen:
            raise AttributeError("Config is frozen")
        object.__setattr__(self, name, value)


class ImageMetadata:
    """Stores image processing metadata with merge capability."""

    def __init__(self):
        self.properties = {}
        self.processing_history = []
        self.access_control = {"role": "viewer", "can_decrypt": False}

    def merge_properties(self, source: dict, target: dict = None):
        """Deep merge source into target properties dict."""
        if target is None:
            target = self.properties

        for key, value in source.items():
            if isinstance(value, dict) and key in target and isinstance(target[key], dict):
                self.merge_properties(value, target[key])
            else:
                target[key] = value
        return target

    def apply_metadata_patch(self, patch: dict):
        """Apply a metadata patch from deserialized image headers."""
        self.merge_properties(patch, self.__dict__)


class EncryptedImageStore:
    """AES-256-CBC encrypted image storage."""

    def __init__(self, master_key: bytes):
        if len(master_key) != 32:
            raise ValueError("Master key must be 32 bytes")
        self._master_key = master_key
        self._backend = default_backend()

    def encrypt_image(self, data: bytes, metadata: ImageMetadata) -> bytes:
        """Encrypt image data with associated metadata."""
        iv = os.urandom(16)
        cipher = Cipher(algorithms.AES(self._master_key), modes.CBC(iv), backend=self._backend)
        encryptor = cipher.encryptor()

        padder = sym_padding.PKCS7(128).padder()
        padded = padder.update(data) + padder.finalize()
        ciphertext = encryptor.update(padded) + encryptor.finalize()

        meta_json = json.dumps(metadata.properties).encode()
        meta_len = struct.pack('<I', len(meta_json))

        mac = hmac.new(self._master_key, iv + ciphertext + meta_len + meta_json, hashlib.sha256).digest()

        return iv + ciphertext + meta_len + meta_json + mac

    def decrypt_image(self, blob: bytes, metadata: ImageMetadata) -> bytes:
        """Decrypt image, checking access control from metadata."""
        if not metadata.access_control.get("can_decrypt", False):
            raise PermissionError("Insufficient privileges to decrypt")

        iv = blob[:16]
        mac_stored = blob[-32:]
        payload = blob[16:-32]

        meta_len_offset = len(payload) - struct.unpack('<I', payload[-4:])[0] - 4
        ciphertext = payload[:meta_len_offset]

        cipher = Cipher(algorithms.AES(self._master_key), modes.CBC(iv), backend=self._backend)
        decryptor = cipher.decryptor()
        padded = decryptor.update(ciphertext) + decryptor.finalize()

        unpadder = sym_padding.PKCS7(128).unpadder()
        return unpadder.update(padded) + unpadder.finalize()


class ImageProcessor:
    """Main image processing pipeline."""

    def __init__(self, config: SecureConfig, store: EncryptedImageStore):
        self.config = config
        self.store = store
        self._transforms = []

    def register_transform(self, name: str, fn):
        self._transforms.append((name, fn))

    def process_upload(self, raw_data: bytes, user_metadata: dict) -> dict:
        """Process an uploaded image with user-supplied metadata."""
        meta = ImageMetadata()

        # Extract embedded metadata from image header (simulated)
        embedded_meta = self._extract_embedded_metadata(raw_data)

        # Apply embedded metadata first
        if embedded_meta:
            meta.apply_metadata_patch(embedded_meta)

        # Then apply user metadata (user metadata has lower priority for security fields)
        safe_user_meta = self._sanitize_user_metadata(user_metadata)
        meta.merge_properties(safe_user_meta)

        # Run transforms
        processed = raw_data
        for name, fn in self._transforms:
            processed = fn(processed, meta)
            meta.processing_history.append(name)

        # Store encrypted
        try:
            blob = self.store.encrypt_image(processed, meta)
            return {"status": "stored", "size": len(blob)}
        except PermissionError as e:
            return {"status": "error", "message": str(e)}

    def _extract_embedded_metadata(self, data: bytes) -> Optional[dict]:
        """Extract JSON metadata from custom image header format.
        Format: first 4 bytes = length of JSON metadata, followed by JSON."""
        if len(data) < 4:
            return None
        meta_len = struct.unpack('<I', data[:4])[0]
        if meta_len == 0 or meta_len > 4096 or meta_len + 4 > len(data):
            return None
        try:
            return json.loads(data[4:4+meta_len].decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None

    def _sanitize_user_metadata(self, user_meta: dict) -> dict:
        """Remove dangerous keys from user-supplied metadata."""
        blocked_keys = {'access_control', 'role', 'can_decrypt', '__class__', '__init__'}
        sanitized = {}
        for k, v in user_meta.items():
            if k not in blocked_keys:
                if isinstance(v, dict):
                    sanitized[k] = self._sanitize_user_metadata(v)
                elif isinstance(v, str) and len(v) < 1024:
                    sanitized[k] = v
                elif isinstance(v, (int, float, bool)):
                    sanitized[k] = v
        return sanitized


def create_pipeline(master_key: bytes) -> ImageProcessor:
    """Factory function to create a configured pipeline."""
    config = SecureConfig({
        "max_size": 10 * 1024 * 1024,
        "allowed_formats": ["png", "jpeg", "webp"],
        "encryption": "aes-256-cbc"
    })
    store = EncryptedImageStore(master_key)
    return ImageProcessor(config, store)
